// tracers
this.tracers = this.tracers.filter(t => (t.t -= dt) > 0);
for (const t of this.tracers) {
  ctx.strokeStyle = `rgba(255, 240, 160, ${t.t / 0.08 * 0.85})`;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(t.x1, t.y1);
  ctx.lineTo(t.x2, t.y2);
  ctx.stroke();
}

// impact sparks: 3D particles with gravity, projected each frame
this.sparks = this.sparks.filter(s => (s.t += dt) < s.life);
if (this.sparks.length) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineCap = 'round';
  for (const s of this.sparks) {
    const k = 1 - s.t / s.life;
    s.vel[1] -= 14 * dt;
    const prev = [...s.pos];
    s.pos[0] += s.vel[0] * dt;
    s.pos[1] += s.vel[1] * dt;
    s.pos[2] += s.vel[2] * dt;
    const a = this.worldToScreen(prev, cam);
    const b = this.worldToScreen(s.pos, cam);
    if (!a || !b) continue;
    ctx.strokeStyle = `rgba(${s.col[0]},${s.col[1]},${s.col[2]},${k * 0.9})`;
    ctx.lineWidth = Math.max(1, 2.4 * k);
    ctx.beginPath();
    ctx.moveTo(a[0], a[1]);
    ctx.lineTo(b[0], b[1]);
    ctx.stroke();
  }
  ctx.restore();
}
